import{_ as p,a0 as r,w as o,s as d,ao as l,I as t,a1 as n,A as i,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何保護 Ubuntu 16.04 上的 NGINX Web 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"如何保護 Ubuntu 16.04 上的 NGINX Web 服務器 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何保護 Ubuntu 16.04 上的 NGINX Web 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何保護 Ubuntu 16.04 上的 NGINX Web 服務器 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170628 Encryption How To Secure an NGINX web server on Ubuntu 16.04","title":"如何保護 Ubuntu 16.04 上的 NGINX Web 服務器","tag":"201708","desc":""},"relativePath":"201708/20170628 Encryption How To Secure an NGINX web server on Ubuntu 16.04.md","filePath":"[post].md"}'),c={name:"201708/20170628 Encryption How To Secure an NGINX web server on Ubuntu 16.04.md"};function h(g,s,b,u,k,f){const a=r("Link");return o(),d("div",null,[s[17]||(s[17]=l('<h1 id="如何保護-ubuntu-16-04-上的-nginx-web-服務器" tabindex="-1">如何保護 Ubuntu 16.04 上的 NGINX Web 服務器 <a class="header-anchor" href="#如何保護-ubuntu-16-04-上的-nginx-web-服務器" aria-label="Permalink to “如何保護 Ubuntu 16.04 上的 NGINX Web 服務器”">​</a></h1><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/le-logo-standard.png" alt="Let&#39;s Encrypt Encryption CA" title="le-logo-standard"></p><h3 id="什麼是-let-s-encrypt" tabindex="-1">什麼是 Let’s Encrypt <a class="header-anchor" href="#什麼是-let-s-encrypt" aria-label="Permalink to “什麼是 Let’s Encrypt”">​</a></h3>',3)),t("p",null,[n(a,{href:"https://letsencrypt.org/"},{default:i(()=>[...s[0]||(s[0]=[e("Let’s Encrypt",-1)])]),_:1}),s[2]||(s[2]=e(" 是互聯網安全研究組織 （ISRG） 提供的免費證書認證機構。它提供了一種輕鬆自動的方式來獲取免費的 SSL/TLS 證書 - 這是在 Web 服務器上啓用加密和 HTTPS 流量的必要步驟。獲取和安裝證書的大多數步驟可以通過使用名為 ",-1)),n(a,{href:"https://certbot.eff.org/"},{default:i(()=>[...s[1]||(s[1]=[e("Certbot",-1)])]),_:1}),s[3]||(s[3]=e(" 的工具進行自動化。",-1))]),s[18]||(s[18]=l(`<p>特別地，該軟件可在可以使用 shell 的服務器上使用：換句話説，它可以通過 SSH 連接使用。</p><p>在本教程中，我們將看到如何使用 <code>certbot</code> 獲取免費的 SSL 證書，並在 Ubuntu 16.04 服務器上使用 Nginx。</p><h3 id="安裝-certbot" tabindex="-1">安裝 Certbot <a class="header-anchor" href="#安裝-certbot" aria-label="Permalink to “安裝 Certbot”">​</a></h3><p>第一步是安裝 <code>certbot</code>，該軟件客户端可以幾乎自動化所有的過程。 Certbot 開發人員維護自己的 Ubuntu 倉庫，其中包含比 Ubuntu 倉庫中存在的軟件更新的軟件。</p><p>添加 Certbot 倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># add-apt-repository ppa:certbot/certbot</span></span></code></pre></div><p>接下來，更新 APT 源列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get update</span></span></code></pre></div><p>此時，可以使用以下 <code>apt</code> 命令安裝 <code>certbot</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get install certbot</span></span></code></pre></div><p>Certbot 現已安裝並可使用。</p><h3 id="獲得證書" tabindex="-1">獲得證書 <a class="header-anchor" href="#獲得證書" aria-label="Permalink to “獲得證書”">​</a></h3><p>有各種 Certbot 插件可用於獲取 SSL 證書。這些插件有助於獲取證書，而證書的安裝和 Web 服務器配置都留給管理員。</p><p>我們使用一個名為 <strong>Webroot</strong> 的插件來獲取 SSL 證書。</p><p>在有能力修改正在提供的內容的情況下，建議使用此插件。在證書頒發過程中不需要停止 Web 服務器。</p><h4 id="配置-nginx" tabindex="-1">配置 NGINX <a class="header-anchor" href="#配置-nginx" aria-label="Permalink to “配置 NGINX”">​</a></h4><p>Webroot 會在 Web 根目錄下的 <code>.well-known</code> 目錄中為每個域創建一個臨時文件。在我們的例子中，Web 根目錄是 <code>/var/www/html</code>。確保該目錄在 Let’s Encrypt 驗證時可訪問。為此，請編輯 NGINX 配置。使用文本編輯器打開 <code>/etc/nginx/sites-available/default</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /etc/nginx/sites-available/default</span></span></code></pre></div><p>在該文件中，在 <code>server</code> 塊內，輸入以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> location ~ /.well-known {</span></span>
<span class="line"><span>    allow all;</span></span>
<span class="line"><span> }</span></span></code></pre></div><p>保存，退出並檢查 NGINX 配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nginx -t</span></span></code></pre></div><p>沒有錯誤的話應該會顯示如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nginx: the configuration file /etc/nginx/nginx.conf syntax is ok</span></span>
<span class="line"><span>nginx: configuration file /etc/nginx/nginx.conf test is successful</span></span></code></pre></div><p>重啓 NGINX：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart nginx</span></span></code></pre></div><h4 id="使用-certbot-獲取證書" tabindex="-1">使用 Certbot 獲取證書 <a class="header-anchor" href="#使用-certbot-獲取證書" aria-label="Permalink to “使用 Certbot 獲取證書”">​</a></h4><p>下一步是使用 Certbot 的 Webroot 插件獲取新證書。在本教程中，我們將保護示例域 www.example.com。需要指定應由證書保護的每個域。執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># certbot certonly --webroot --webroot-path=/var/www/html -d www.example.com</span></span></code></pre></div><p>在此過程中，Cerbot 將詢問有效的電子郵件地址，用於進行通知。還會要求與 EFF 分享，但這不是必需的。在同意服務條款之後，它將獲得一個新的證書。</p><p>最後，目錄 <code>/etc/letsencrypt/archive</code> 將包含以下文件：</p><ul><li><code>chain.pem</code>：Let’s Encrypt 加密鏈證書。</li><li><code>cert.pem</code>：域名證書。</li><li><code>fullchain.pem</code>：<code>cert.pem</code>和 <code>chain.pem</code> 的組合。</li><li><code>privkey.pem</code>：證書的私鑰。</li></ul><p>Certbot 還將創建符號鏈接到 <code>/etc/letsencrypt/live/domain_name/</code> 中的最新證書文件。這是我們將在服務器配置中使用的路徑。</p><h3 id="在-nginx-上配置-ssl-tls" tabindex="-1">在 NGINX 上配置 SSL/TLS <a class="header-anchor" href="#在-nginx-上配置-ssl-tls" aria-label="Permalink to “在 NGINX 上配置 SSL/TLS”">​</a></h3><p>下一步是服務器配置。在 <code>/etc/nginx/snippets/</code> 中創建一個新的代碼段。 <strong>snippet</strong> 是指一段配置，可以包含在虛擬主機配置文件中。如下創建一個新的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /etc/nginx/snippets/secure-example.conf</span></span></code></pre></div><p>該文件的內容將指定證書和密鑰位置。粘貼以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssl_certificate /etc/letsencrypt/live/domain_name/fullchain.pem;</span></span>
<span class="line"><span>ssl_certificate_key /etc/letsencrypt/live/domain_name/privkey.pem;</span></span></code></pre></div><p>在我們的例子中，<code>domain_name</code> 是 <code>example.com</code>。</p><h4 id="編輯-nginx-配置" tabindex="-1">編輯 NGINX 配置 <a class="header-anchor" href="#編輯-nginx-配置" aria-label="Permalink to “編輯 NGINX 配置”">​</a></h4><p>編輯默認虛擬主機文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /etc/nginx/sites-available/default</span></span></code></pre></div><p>如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>server {</span></span>
<span class="line"><span> listen 80 default_server;</span></span>
<span class="line"><span> listen [::]:80 default_server;</span></span>
<span class="line"><span> server_name www.example.com</span></span>
<span class="line"><span> return 301 https://$server_name$request_uri;</span></span>
<span class="line"><span></span></span>
<span class="line"><span> # SSL configuration</span></span>
<span class="line"><span> #</span></span>
<span class="line"><span> listen 443 ssl default_server;</span></span>
<span class="line"><span> listen [::]:443 ssl default_server;</span></span>
<span class="line"><span> include snippets/secure-example.conf</span></span>
<span class="line"><span> #</span></span>
<span class="line"><span> # Note: You should disable gzip for SSL traffic.</span></span>
<span class="line"><span> # See: https://bugs.debian.org/773332</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>這將啓用 NGINX 加密功能。</p><p>保存、退出並檢查 NGINX 配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nginx -t</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nginx: the configuration file /etc/nginx/nginx.conf syntax is ok</span></span>
<span class="line"><span>nginx: configuration file /etc/nginx/nginx.conf test is successful</span></span></code></pre></div><p>重啓 NGINX：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl restart nginx</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>按照上述步驟，此時我們已經擁有了一個安全的基於 NGINX 的 Web 服務器，它由 Certbot 和 Let’s Encrypt 提供加密。這只是一個基本配置，當然你可以使用許多 NGINX 配置參數來個性化所有東西，但這取決於特定的 Web 服務器要求。</p><hr>`,52)),t("p",null,[s[5]||(s[5]=e("via: ",-1)),n(a,{href:"https://www.unixmen.com/encryption-secure-nginx-web-server-ubuntu-16-04/"},{default:i(()=>[...s[4]||(s[4]=[e("https://www.unixmen.com/encryption-secure-nginx-web-server-ubuntu-16-04/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),n(a,{href:"https://www.unixmen.com/author/tutan/"},{default:i(()=>[...s[6]||(s[6]=[e("Giuseppe Molica",-1)])]),_:1}),s[10]||(s[10]=e(" 譯者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[7]||(s[7]=[e("geekpi",-1)])]),_:1}),s[11]||(s[11]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[14]||(s[14]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[12]||(s[12]=[e("LCTT",-1)])]),_:1}),s[15]||(s[15]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...s[13]||(s[13]=[e("Linux中國",-1)])]),_:1}),s[16]||(s[16]=e(" 榮譽推出",-1))])])}const C=p(c,[["render",h]]);export{y as __pageData,C as default};
